public void setProperty(Object bean, String name, Object value)
        throws IllegalAccessException, InvocationTargetException {

    if (log.isTraceEnabled()) {
        log.trace("  setProperty(" + bean + ", " + name + ", " + value + ")");
    }

    Object target = bean;
    Resolver resolver = getPropertyUtils().getResolver();
    while (resolver.hasNested(name)) {
        try {
            target = getPropertyUtils().getProperty(target, resolver.next(name));
            if (target == null) {
                return;
            }
            name = resolver.remove(name);
        } catch (NoSuchMethodException e) {
            return;
        }
    }

    if (log.isTraceEnabled()) {
        log.trace("    Target bean = " + target);
        log.trace("    Target name = " + name);
    }

    String propName = resolver.getProperty(name);
    Class<?> type = getPropertyUtils().getPropertyType(target, name);
    if (type == null) {
        return; // Skip this property setter
    }

    Object newValue = convert(value, type);

    try {
        getPropertyUtils().setProperty(target, name, newValue);
    } catch (NoSuchMethodException e) {
        throw new InvocationTargetException(e, "Cannot set " + propName);
    }
}

private Object convert(Object value, Class<?> type) {
    if (value == null) {
        return null;
    }
    if (type.isArray()) {
        if (value instanceof String) {
            return getConvertUtils().convert((String) value, type);
        } else if (value instanceof String[]) {
            return getConvertUtils().convert((String[]) value, type);
        }
    } else {
        return getConvertUtils().convert(value, type);
    }
    return null;
}

